import (
	"fmt"
	"html"
	"io"
	"net"
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"syscall"
	"time"

	"github.com/labstack/echo/v4"
)

// Request body
type PreviewRequest struct {
	URL string `json:"url"`
}

// Response body
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
}

// isBlockedIP checks if an IP address is private, loopback, link-local, or otherwise blocked.
func isBlockedIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
		return true
	}
	// Block Shared Address Space (Carrier-grade NAT)
	_, sharedSpace, _ := net.ParseCIDR("100.64.0.0/10")
	if sharedSpace.Contains(ip) {
		return true
	}
	return false
}

func FetchURLPreview(ctx echo.Context) error {
	req := new(PreviewRequest)
	if err := ctx.Bind(req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid JSON"})
	}

	// Validate URL
	parsedURL, err := url.Parse(req.URL)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid URL format"})
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Only HTTP/HTTPS URLs are allowed"})
	}

	if parsedURL.Hostname() == "" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid URL format"})
	}

	// SSRF Protection: Custom Dialer with Control function
	// The Control function is called after DNS resolution but before the socket connects.
	// This prevents DNS rebinding attacks and ensures we never connect to a private IP.
	dialer := &net.Dialer{
		Timeout: 3 * time.Second,
		Control: func(network, address string, c syscall.RawConn) error {
			host, _, err := net.SplitHostPort(address)
			if err != nil {
				return err
			}
			ip := net.ParseIP(host)
			if ip == nil {
				return fmt.Errorf("invalid IP address")
			}
			if isBlockedIP(ip) {
				return fmt.Errorf("access to private IP addresses is forbidden")
			}
			return nil
		},
	}

	transport := &http.Transport{
		DialContext: dialer.DialContext,
	}

	client := &http.Client{
		Timeout:   5 * time.Second,
		Transport: transport,
	}

	httpReq, err := http.NewRequest(http.MethodGet, req.URL, nil)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid URL format"})
	}
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	resp, err := client.Do(httpReq)
	if err != nil {
		if strings.Contains(err.Error(), "private IP addresses") {
			return ctx.JSON(http.StatusForbidden, map[string]string{"error": "Access to private IP addresses is forbidden"})
		}
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to fetch URL"})
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": fmt.Sprintf("HTTP %d", resp.StatusCode)})
	}

	// Limit response body to 10MB to prevent OOM (Denial of Service)
	body, err := io.ReadAll(io.LimitReader(resp.Body, 10<<20))
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": "Failed to read response body"})
	}

	title, description := extractTitleAndDescription(body)

	return ctx.JSON(http.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
	})
}

func extractTitleAndDescription(htmlContent []byte) (string, string) {
	var title, description string

	// Extract Title
	titleRe := regexp.MustCompile(`(?is)<title[^>]*>(.*?)</title>`)
	if matches := titleRe.FindSubmatch(htmlContent); len(matches) > 1 {
		title = strings.TrimSpace(string(matches[1]))
	}

	// Extract Meta Description
	descRe1 := regexp.MustCompile(`(?is)<meta\s+[^>]*?name\s*=\s*["']?description["']?[^>]*?content\s*=\s*["']([^"']*)["']`)
	descRe2 := regexp.MustCompile(`(?is)<meta\s+[^>]*?content\s*=\s*["']([^"']*)["'][^>]*?name\s*=\s*["']?description["']?`)

	if matches := descRe1.FindSubmatch(htmlContent); len(matches) > 1 {
		description = strings.TrimSpace(string(matches[1]))
	} else if matches := descRe2.FindSubmatch(htmlContent); len(matches) > 1 {
		description = strings.TrimSpace(string(matches[1]))
	}

	return html.UnescapeString(title), html.UnescapeString(description)
}

func main() {
	e := echo.New()
	e.POST("/preview", FetchURLPreview)
	e.Logger.Fatal(e.Start(":8080"))
}

