					description = html.UnescapeString(strings.TrimSpace(string(contentMatch[1])))
					break
				}
			}
		}
	}

	return title, description
}

func main() {
	e := echo.New()
	e.POST("/preview", FetchURLPreview)
	e.Logger.Fatal(e.Start(":8080"))
}

