// safeDialContext prevents SSRF by resolving DNS and validating the IP address
// before establishing a connection. It also prevents DNS rebinding attacks.
func safeDialContext(ctx context.Context, network, addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, fmt.Errorf("invalid address: %w", err)
	}

	ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
	if err != nil {
		return nil, fmt.Errorf("DNS lookup failed: %w", err)
	}

	dialer := &net.Dialer{
		Timeout: 5 * time.Second,
	}

	var lastErr error
	for _, ipAddr := range ips {
		ip := ipAddr.IP
		// Block private, loopback, link-local, and unspecified IPs
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
			return nil, errors.New("access to internal/private IP addresses is forbidden")
		}

		// Dial the specific IP directly to prevent TOCTOU / DNS rebinding vulnerabilities
		targetAddr := net.JoinHostPort(ip.String(), port)
		conn, err := dialer.DialContext(ctx, network, targetAddr)
		if err == nil {
			return conn, nil
		}
		lastErr = err
	}

	if lastErr != nil {
		return nil, lastErr
	}
	return nil, errors.New("no suitable IP address found")
}

func FetchURLPreview(ctx echo.Context) error {
	req := new(PreviewRequest)
	if err := ctx.Bind(req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "Invalid JSON"})
	}

