	content := string(htmlContent)

	var title, description string

	// Extract Title
	reTitle := regexp.MustCompile(`(?is)<title[^>]*>(.*?)</title>`)
	if m := reTitle.FindStringSubmatch(content); len(m) > 1 {
		title = strings.TrimSpace(m[1])
	}

