	metas := reMeta.FindAllString(content, -1)
	reName := regexp.MustCompile(`(?i)name=(?:"description"|'description')`)
	reContent := regexp.MustCompile(`(?i)content=(?:"([^"]*)"|'([^']*)')`)

	for _, meta := range metas {
		if reName.MatchString(meta) {
			if m := reContent.FindStringSubmatch(meta); len(m) > 2 {
				if m[1] != "" {
					description = strings.TrimSpace(m[1])
				} else {
					description = strings.TrimSpace(m[2])
				}
				break
			}
		}
	}

	// Unescape HTML entities
	return html.UnescapeString(title), html.UnescapeString(description)
