func extractTitleAndDesc(body string) (string, string) {
	var title, desc string

	// Extract title using regex
	reTitle := regexp.MustCompile(`(?is)<title\s*(?:[^>"']|"[^"]*"|'[^']*')*>(.*?)</title>`)
	if matches := reTitle.FindStringSubmatch(body); len(matches) > 1 {
		title = strings.TrimSpace(matches[1])
	}

	// Extract meta tags using regex
	reMeta := regexp.MustCompile(`(?is)<meta\s+(?:[^>"']|"[^"]*"|'[^']*')*>`)
	metaTags := reMeta.FindAllString(body, -1)

	// Extract attributes from meta tags
	reAttr := regexp.MustCompile(`(?i)([a-zA-Z]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))`)

	for _, meta := range metaTags {
