	"io"
	"net/http"
	"strings"
	"time"

	"github.com/labstack/echo/v4"
	htmltokenizer "golang.org/x/net/html"
)

type PreviewRequest struct {
	URL string `json:"url"`
}

type PreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

func FetchURLPreview(ctx echo.Context) error {
	var req PreviewRequest
	if err := ctx.Bind(&req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "invalid request body"})
	}

	if req.URL == "" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "url is required"})
	}

	reqCtx, cancel := context.WithTimeout(ctx.Request().Context(), 3*time.Second)
	defer cancel()

	httpReq, err := http.NewRequestWithContext(reqCtx, http.MethodGet, req.URL, nil)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "invalid url"})
	}

	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.JSON(http.StatusBadGateway, map[string]string{"error": "failed to fetch url"})
	}
	defer resp.Body.Close()

	// Limit response body to 10MB to prevent OOM
	bodyReader := io.LimitReader(resp.Body, 10*1024*1024)
	title, description := parseHTML(bodyReader)

	return ctx.JSON(http.StatusOK, PreviewResponse{
		Title:       title,
		Description: description,
	})
}

func parseHTML(r io.Reader) (string, string) {
	var description string
	var inTitle bool
	var titleBuilder strings.Builder

	z := htmltokenizer.NewTokenizer(r)
	for {
		tt := z.Next()
		switch tt {
		case htmltokenizer.ErrorToken:
			return strings.TrimSpace(titleBuilder.String()), description
		case htmltokenizer.StartTagToken, htmltokenizer.SelfClosingTagToken:
			tn, hasAttr := z.TagName()
			tagName := string(tn)
			if tagName == "title" {
				inTitle = true
			}
			if tagName == "meta" && hasAttr {
				var name, content string
				for {
					key, val, more := z.TagAttr()
					k := strings.ToLower(string(key))
					v := string(val)
					if k == "name" {
						name = strings.ToLower(v)
					} else if k == "content" {
						content = v
					}
					if !more {
						break
					}
				}
				if name == "description" && description == "" {
					description = html.UnescapeString(content)
				}
			}
		case htmltokenizer.EndTagToken:
			tn, _ := z.TagName()
			if string(tn) == "title" {
				inTitle = false
			}
		case htmltokenizer.TextToken:
			if inTitle {
				titleBuilder.WriteString(html.UnescapeString(string(z.Text())))
			}
		}
	}
}

func main() {
	e := echo.New()
	e.POST("/preview", FetchURLPreview)
	e.Logger.Fatal(e.Start(":8080"))
}

