	gtIdx := strings.Index(htmlContent[startIdx:], ">")
	if gtIdx == -1 {
		return ""
	}
	startIdx += gtIdx + 1
	endIdx := strings.Index(lower[startIdx:], "</title")
	if endIdx == -1 {
